const STORAGE_KEY = 'cyber-adv.case001.prototype.v2';
const DEFAULT_STATE = { activeTab: 'evidence', selectedCharacterId: 'ayaka', selectedEvidenceId: null, evidence: [], logs: [], facts: [], completedEvents: [], examinedInvestigations: [] };
let scenario; let state; const ui = { people: document.querySelector('#people-list'), evidence: document.querySelector('#evidence-list'), detail: document.querySelector('#detail-view'), dialog: document.querySelector('#inspection-dialog'), content: document.querySelector('#inspection-content'), peopleCount: document.querySelector('#people-count'), evidenceCount: document.querySelector('#evidence-count'), saveStatus: document.querySelector('#save-status'), toast: document.querySelector('#toast') }; let toastTimer;
const clone = (value) => JSON.parse(JSON.stringify(value));
function save() { localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...state, savedAt: new Date().toISOString() })); ui.saveStatus.textContent = `保存済み ${new Date().toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' })}`; }
function toast(message) { ui.toast.textContent = message; ui.toast.classList.add('is-visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => ui.toast.classList.remove('is-visible'), 2000); }
function find(collection, id) { return (scenario[collection] || []).find((item) => item.id === id); }
function asset(path, fallback = '') { return path ? `./${path}` : fallback; }
function button(className, label, onClick, selected = false) { const el = document.createElement('button'); el.type = 'button'; el.className = `${className}${selected ? ' is-selected' : ''}`; el.textContent = label; el.addEventListener('click', onClick); return el; }
function available(condition) { if (!condition) return true; if (condition.type === 'evidence') return state.evidence.includes(condition.targetId); if (condition.type === 'fact') return state.facts.includes(condition.targetId); if (condition.type === 'event') return state.completedEvents.includes(condition.targetId); if (condition.type === 'conversation') return state.completedEvents.includes(condition.targetId); if (condition.type === 'investigation') return state.examinedInvestigations.includes(condition.targetId); if (condition.type === 'logRow') return state.completedEvents.includes(condition.targetId); return false; }
function applyEvent(eventId) { if (!eventId || state.completedEvents.includes(eventId)) return; const event = find('events', eventId); if (!event) return; for (const effect of event.effects || []) { if (effect.type !== 'add') continue; const [collection, id] = effect.target.split('.'); if (['evidence', 'logs', 'facts'].includes(collection) && !state[collection].includes(id)) state[collection].push(id); } state.completedEvents.push(eventId); }
function renderPeople() { ui.people.replaceChildren(); ui.peopleCount.textContent = scenario.characters.length; for (const character of scenario.characters) { const el = button('list-item', '', () => { state.selectedCharacterId = character.id; state.selectedEvidenceId = null; state.selectedFactId = null; render(); save(); }, character.id === state.selectedCharacterId && !state.selectedEvidenceId); const avatar = document.createElement('span'); avatar.className = `avatar${character.id === state.selectedCharacterId ? ' is-accent' : ''}`; if (character.icon || scenario.defaults?.characterIcon) { const image = document.createElement('img'); image.src = asset(character.icon || scenario.defaults.characterIcon); image.alt = ''; avatar.append(image); } else avatar.textContent = character.name?.slice(0, 1) || '?'; const copy = document.createElement('span'); copy.className = 'item-copy'; const name = document.createElement('span'); name.className = 'item-name'; name.textContent = character.name; const role = document.createElement('span'); role.className = 'item-meta'; role.textContent = character.role || ''; copy.append(name, role); el.append(avatar, copy); ui.people.append(el); } }
function renderEvidence() { ui.evidence.replaceChildren(); const tab = state.activeTab; document.querySelectorAll('.tab-button').forEach((el) => { const active = el.dataset.tab === tab; el.classList.toggle('is-active', active); el.setAttribute('aria-selected', String(active)); }); if (tab === 'logs') { const logs = scenario.logs.filter((log) => state.logs.includes(log.id)); ui.evidenceCount.textContent = logs.length; logs.forEach((log) => { const el = button('list-item', '', () => { state.selectedCharacterId = null; state.selectedEvidenceId = log.id; render(); save(); }, state.selectedEvidenceId === log.id); const avatar = document.createElement('span'); avatar.className = 'avatar'; avatar.textContent = 'LOG'; const copy = document.createElement('span'); copy.className = 'item-copy'; const name = document.createElement('span'); name.className = 'item-name'; name.textContent = log.name; const meta = document.createElement('span'); meta.className = 'item-meta'; meta.textContent = 'ログファイル'; copy.append(name, meta); el.append(avatar, copy); ui.evidence.append(el); }); return; } if (tab === 'facts') { const facts = scenario.facts.filter((fact) => state.facts.includes(fact.id)); ui.evidenceCount.textContent = facts.length; facts.forEach((fact) => { const el = button('list-item', '', () => { state.selectedFactId = fact.id; state.selectedCharacterId = null; state.selectedEvidenceId = null; render(); save(); }, state.selectedFactId === fact.id); const avatar = document.createElement('span'); avatar.className = 'avatar is-accent'; avatar.textContent = '報'; const copy = document.createElement('span'); copy.className = 'item-copy'; const name = document.createElement('span'); name.className = 'item-name'; name.textContent = fact.name; copy.append(name); el.append(avatar, copy); ui.evidence.append(el); }); return; } const evidence = scenario.evidence.filter((item) => state.evidence.includes(item.id)); ui.evidenceCount.textContent = evidence.length; evidence.forEach((item) => { const el = button('list-item', '', () => { state.selectedCharacterId = null; state.selectedEvidenceId = item.id; state.selectedFactId = null; render(); save(); }, state.selectedEvidenceId === item.id); const avatar = document.createElement('span'); avatar.className = 'avatar is-accent'; if (item.icon || scenario.defaults?.evidenceIcon) { const image = document.createElement('img'); image.src = asset(item.icon || scenario.defaults.evidenceIcon); image.alt = ''; avatar.append(image); } else avatar.textContent = 'EV'; const copy = document.createElement('span'); copy.className = 'item-copy'; const name = document.createElement('span'); name.className = 'item-name'; name.textContent = item.name; copy.append(name); el.append(avatar, copy); ui.evidence.append(el); }); if (!evidence.length) { const empty = document.createElement('p'); empty.className = 'empty-state'; empty.textContent = 'まだ証拠品がありません。人物に話を聞いて資料を集めましょう。'; ui.evidence.append(empty); } }
function background(path) { ui.detail.style.backgroundImage = `linear-gradient(90deg, rgba(9,16,25,.18), rgba(9,16,25,.76)), url("${asset(path || scenario.defaults?.background)}")`; ui.detail.style.backgroundSize = 'cover'; ui.detail.style.backgroundPosition = 'center'; }
function renderPerson(character) { background(character.background); const header = document.createElement('div'); header.className = 'detail-topline'; header.textContent = 'PERSONNEL FILE / 聞き込み対象'; const card = document.createElement('div'); card.className = 'detail-card'; const portrait = document.createElement('div'); portrait.className = 'portrait'; const image = document.createElement('img'); image.src = asset(character.icon || scenario.defaults?.characterIcon); image.alt = character.name; portrait.append(image); const copy = document.createElement('div'); copy.className = 'detail-copy'; const role = document.createElement('div'); role.className = 'detail-role'; role.textContent = character.role || ''; const name = document.createElement('h2'); name.textContent = character.name; const description = document.createElement('p'); description.className = 'detail-description'; description.textContent = character.description || ''; copy.append(role, name, description); for (const conversation of scenario.conversations.filter((entry) => entry.nodes?.some((node) => node.speakerId === character.id) && available(entry.requires))) { const done = state.completedEvents.includes(conversation.id) || state.completedEvents.includes(conversation.completionEventId); copy.append(button('action-button', done ? '会話済み' : conversation.title, () => openConversation(conversation), done)); } card.append(portrait, copy); ui.detail.replaceChildren(header, card); }
function renderEvidenceDetail(item) { background(item.background); const header = document.createElement('div'); header.className = 'detail-topline'; header.textContent = 'EVIDENCE FILE / 証拠品'; const card = document.createElement('div'); card.className = 'detail-card'; const portrait = document.createElement('div'); portrait.className = 'portrait evidence-art'; if (item.icon || scenario.defaults?.evidenceIcon) { const image = document.createElement('img'); image.src = asset(item.icon || scenario.defaults.evidenceIcon); image.alt = item.name; portrait.append(image); } else portrait.textContent = 'EV'; const copy = document.createElement('div'); copy.className = 'detail-copy'; const name = document.createElement('h2'); name.textContent = item.name; const description = document.createElement('p'); description.className = 'detail-description'; description.textContent = item.description || ''; const action = button('action-button', '証拠品を調べる', () => openInvestigation(item)); copy.append(name, description, action); card.append(portrait, copy); ui.detail.replaceChildren(header, card); }
function renderLog(log) { background(log.background); const header = document.createElement('div'); header.className = 'detail-topline'; header.textContent = 'LOG FILE / ログ調査'; const title = document.createElement('h2'); title.textContent = log.name; const intro = document.createElement('p'); intro.className = 'detail-description'; intro.textContent = log.description || ''; const view = document.createElement('div'); view.className = 'log-view'; view.append(title, intro); for (const rowData of log.rows || []) { const row = button('log-row', `${rowData.time || ''}  ${rowData.text}`, () => { applyEvent(rowData.completionEventId); render(); save(); toast('ログから判明事項を取得しました'); }, !rowData.important || state.completedEvents.includes(rowData.completionEventId)); view.append(row); } ui.detail.replaceChildren(header, view); }
function renderDetail() { if (state.activeTab === 'facts') { const fact = find('facts', state.selectedFactId); ui.detail.style.backgroundImage = ''; if (fact && state.facts.includes(fact.id)) { ui.detail.innerHTML = `<div class="detail-topline">INVESTIGATION REPORT / 捜査報告書</div><article class="fact-report"><div class="report-label">判明事項</div><h2></h2><p></p></article>`; ui.detail.querySelector('h2').textContent = fact.name; ui.detail.querySelector('p').textContent = fact.description || ''; } return; } const log = state.activeTab === 'logs' ? find('logs', state.selectedEvidenceId) : null; if (log) return renderLog(log); const evidence = find('evidence', state.selectedEvidenceId); if (evidence && state.evidence.includes(evidence.id)) return renderEvidenceDetail(evidence); const character = find('characters', state.selectedCharacterId) || scenario.characters[0]; if (character) { state.selectedCharacterId = character.id; renderPerson(character); } }
function render() { renderPeople(); renderEvidence(); renderDetail(); }
function openInvestigation(item) { ui.content.replaceChildren(); const prompt = document.createElement('p'); prompt.className = 'detail-description'; prompt.textContent = `「${item.name}」のどこを調べますか？`; const choices = document.createElement('div'); choices.className = 'inspection-choices'; for (const investigation of item.investigations || []) { const done = state.examinedInvestigations.includes(investigation.id); choices.append(button('action-button', done ? `${investigation.label}（調査済み）` : investigation.label, () => { if (done) return; state.examinedInvestigations.push(investigation.id); applyEvent(investigation.completionEventId); render(); save(); toast('調査結果を記録しました'); openInvestigation(item); }, done)); } ui.content.append(prompt, choices); ui.dialog.showModal(); }
function openConversation(conversation) { let node = findNode(conversation, conversation.startNodeId); function draw() { while (node?.routes?.length) { const route = node.routes.find((entry) => available(entry.requires)); node = route ? (route.nextNodeId ? findNode(conversation, route.nextNodeId) : null) : null; } ui.content.replaceChildren(); if (!node) { ui.dialog.close(); applyEvent(conversation.completionEventId); state.completedEvents.push(conversation.id); render(); save(); return; } const text = document.createElement('p'); text.className = 'inspection-result'; text.style.whiteSpace = 'pre-line'; text.textContent = node.text || ''; ui.content.append(text); if (node.choices?.length) { const choices = document.createElement('div'); choices.className = 'inspection-choices'; node.choices.filter((choice) => available(choice.requires)).forEach((choice) => choices.append(button('action-button', choice.text, () => { node = findNode(conversation, choice.nextNodeId); draw(); }))); ui.content.append(choices); } else if (node.nextNodeId) ui.content.append(button('action-button', '次へ', () => { node = findNode(conversation, node.nextNodeId); draw(); })); else ui.content.append(button('action-button', '会話を終了', () => { ui.dialog.close(); applyEvent(conversation.completionEventId); state.completedEvents.push(conversation.id); render(); save(); })); } draw(); ui.dialog.showModal(); }
function findNode(conversation, id) { return (conversation.nodes || []).find((node) => node.id === id); }
async function start() { const response = await fetch('./case001.json'); if (!response.ok) throw new Error('シナリオデータを読み込めませんでした'); scenario = await response.json(); try { state = { ...DEFAULT_STATE, ...JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}') }; } catch { state = clone(DEFAULT_STATE); } state.evidence = state.evidence.filter((id) => find('evidence', id)); state.logs = (state.logs || []).filter((id) => find('logs', id)); state.facts = state.facts.filter((id) => find('facts', id)); document.querySelectorAll('.tab-button').forEach((tab) => tab.addEventListener('click', () => { state.activeTab = tab.dataset.tab; state.selectedEvidenceId = null; render(); save(); })); document.querySelector('#inspection-close').addEventListener('click', () => ui.dialog.close()); document.querySelector('#save-button').addEventListener('click', () => { save(); toast('保存しました'); }); document.querySelector('#reset-button').addEventListener('click', () => { localStorage.removeItem(STORAGE_KEY); state = clone(DEFAULT_STATE); render(); save(); toast('試作データをリセットしました'); }); render(); save(); }
start().catch((error) => { ui.detail.textContent = error.message; ui.saveStatus.textContent = '読み込みに失敗'; });

